					baseline,
					declare({ revision: PINNED_REVISION }),
				).catch(() => null);
				expect(record?.pin?.repository ?? null).toBeNull();
				expect(record?.pin?.ref ?? null).toBeNull();
			} finally {
				await rm(workspace, { recursive: true, force: true });
			}
		});
