		const result = await analyzeCorpusConformance({ rootDir: root, runRecords: [] });
		const published = JSON.parse(
			await readFile(
				path.join(root, 'evidence/trust/current/corpus-conformance.json'),
				'utf8',
			),
		) as typeof result;
